-- MariaDB baseline derived from the current JPA mapping, reviewed for binary assets and uniqueness.
create table accounts (id bigint not null auto_increment, association_id bigint not null, balance decimal(38,2), code varchar(255) not null, created_at datetime(6), is_active bit, name varchar(255) not null, parent_account_id bigint, type enum ('ASSET','EQUITY','EXPENSE','LIABILITY','REVENUE') not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table activities (id bigint not null auto_increment, association_id bigint not null, cancellation_date date, cancellation_reason varchar(255), category varchar(255), cost decimal(38,2) not null, created_at datetime(6), description TEXT, document_path varchar(255), end_date date, end_time time(6), generate_invoice bit, image_path varchar(255), is_active bit, location varchar(255), max_participants integer, name varchar(255) not null, require_registration bit, schedule_details varchar(255), start_date date, start_time time(6), subscription_type varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table activity_costs (id bigint not null auto_increment, activity_id bigint not null, amount decimal(38,2) not null, category varchar(255) not null, created_at datetime(6), incurred_date date not null, description varchar(255) not null, frequency varchar(255), is_recurring bit, notes TEXT, receipt_path varchar(255), supplier varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table activity_instructors (id bigint not null auto_increment, activity_id bigint not null, certifications varchar(255), compensation decimal(38,2), compensation_type varchar(255), created_at datetime(6), email varchar(255), first_name varchar(255), is_active bit, last_name varchar(255), notes TEXT, phone varchar(255), specialization varchar(255), updated_at datetime(6), user_association_id bigint, primary key (id)) engine=InnoDB;
create table activity_participants (id bigint not null auto_increment, activity_id bigint not null, amount_paid decimal(38,2), cancellation_date date, cancellation_reason varchar(255), coupon_code varchar(255), created_at datetime(6), discount_amount decimal(38,2), discount_type varchar(255), expiration_date date, invoice_id bigint, is_active bit, is_paid bit, notes TEXT, original_amount decimal(38,2), payment_date date, payment_method varchar(255), registration_date date not null, updated_at datetime(6), user_id bigint not null, primary key (id)) engine=InnoDB;
create table activity_schedules (id bigint not null auto_increment, activity_id bigint not null, created_at datetime(6), day_of_week integer not null, end_time time(6) not null, instructor_id bigint, is_active bit, location varchar(255), notes TEXT, start_time time(6) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table annual_balance_lines (id bigint not null auto_increment, amount decimal(38,2), balance_id bigint not null, category_id bigint, label varchar(255) not null, notes varchar(255), previous_year_amount decimal(38,2), section varchar(255) not null, sort_order integer, is_subtotal bit, variance decimal(38,2), variance_pct decimal(38,2), primary key (id)) engine=InnoDB;
create table annual_balances (id bigint not null auto_increment, approved_at datetime(6), approved_by bigint, association_id bigint not null, checksum varchar(255), closing_fund decimal(38,2), computed_at datetime(6), created_at datetime(6), net_result decimal(38,2), notes varchar(255), opening_fund decimal(38,2), pdf_path varchar(255), signatories TEXT, status varchar(255), title varchar(255) not null, total_expenses decimal(38,2), total_income decimal(38,2), updated_at datetime(6), `year` integer not null, primary key (id)) engine=InnoDB;
create table assemblies (id bigint not null auto_increment, association_id bigint not null, created_at datetime(6), `date` datetime(6), description varchar(255), end_time varchar(255), first_call_quorum float(53), is_quorum_reached bit, location varchar(255), minutes_path varchar(255), notes TEXT, president varchar(255), second_call_quorum float(53), secretary varchar(255), start_time varchar(255), status varchar(255), title varchar(255), type varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table assembly_documents (id bigint not null auto_increment, assembly_id bigint not null, created_at datetime(6), description varchar(255), file_path varchar(255) not null, file_size bigint, is_mandatory bit, mime_type varchar(255), name varchar(255) not null, type varchar(255) not null, primary key (id)) engine=InnoDB;
create table assembly_motions (id bigint not null auto_increment, assembly_id bigint not null, created_at datetime(6), decision_summary TEXT, decision_taken varchar(255), description TEXT, is_approved bit, is_planned bit, notes TEXT, order_number integer, title varchar(255) not null, updated_at datetime(6), valid_votes integer, votes_abstain integer, votes_against integer, votes_in_favor integer, voting_type varchar(255), primary key (id)) engine=InnoDB;
create table assembly_participants (id bigint not null auto_increment, assembly_id bigint not null, check_in_time datetime(6), check_out_time datetime(6), notes varchar(255), participation_type varchar(255), proxy_receiver_id bigint, role varchar(255), user_association_id bigint not null, primary key (id)) engine=InnoDB;
create table assembly_votes (id bigint not null auto_increment, assembly_id bigint not null, created_at datetime(6), motion_id bigint not null, notes varchar(255), user_association_id bigint not null, vote varchar(255) not null, primary key (id)) engine=InnoDB;
create table association_deadlines (id bigint not null auto_increment, association_id bigint not null, category varchar(255), completed_at datetime(6), completed_by bigint, created_at datetime(6), description TEXT, due_date date not null, recurring bit not null, recurring_months integer, reminder_days integer, status varchar(255), title varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table association_documents (id bigint not null auto_increment, association_id bigint not null, created_at datetime(6), document_type varchar(255) not null, file_path varchar(255) not null, file_size bigint, mime_type varchar(255), title varchar(255) not null, updated_at datetime(6), uploaded_by bigint, version integer, primary key (id)) engine=InnoDB;
create table association_locations (id bigint not null auto_increment, address varchar(255), association_id bigint not null, city varchar(255), country varchar(255), created_at datetime(6), email varchar(255), is_primary bit, location_type varchar(255) not null, name varchar(255), notes TEXT, phone varchar(255), postal_code varchar(255), province varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table associations (id bigint not null auto_increment, address varchar(255), base_membership_fee float(53), city varchar(255), created_at datetime(6), db_host varchar(255), db_name varchar(255), db_password varchar(255), db_port integer, db_ssl bit, db_type varchar(255), db_user varchar(255), description TEXT, email varchar(255) not null, federation_provider varchar(255), federation_registered_at datetime(6), federation_registration_number varchar(255), foundation_date date, is_active bit, logo longblob, membership_number_format varchar(255), name varchar(255) not null, partner_logo_path varchar(255), password varchar(255), phone varchar(255), president varchar(255), province varchar(255), regulation_path varchar(255), secondary_logo_path varchar(255), secretary varchar(255), slug varchar(255) not null, statute_path varchar(255), tax_code varchar(255), treasurer varchar(255), type varchar(255), updated_at datetime(6), use_remote_db bit, vat_number varchar(255), vice_president varchar(255), zip_code varchar(255), primary key (id)) engine=InnoDB;
create table attendance_records (id bigint not null auto_increment, check_in_time time(6), member_id bigint, notes varchar(255), session_id bigint, status varchar(255), user_id bigint, primary key (id)) engine=InnoDB;
create table attendance_sessions (id bigint not null auto_increment, activity_id bigint, created_at datetime(6), `date` date, end_time time(6), instructor_id bigint, notes varchar(255), start_time time(6), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table audit_log (id bigint not null auto_increment, action varchar(255) not null, association_id bigint, created_at datetime(6), description TEXT, entity_id bigint, entity_type varchar(255) not null, ip_address varchar(255), new_value TEXT, old_value TEXT, user_id bigint, primary key (id)) engine=InnoDB;
create table budget_lines (id bigint not null auto_increment, actual_amount decimal(38,2), budget_id bigint not null, budgeted_amount decimal(38,2) not null, category_id bigint, created_at datetime(6), forecast_amount decimal(38,2), label varchar(255) not null, notes varchar(255), sort_order integer, type varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table budgets (id bigint not null auto_increment, approved_at datetime(6), approved_by bigint, association_id bigint not null, created_at datetime(6), name varchar(255) not null, notes varchar(255), status varchar(255) not null, updated_at datetime(6), `year` integer not null, primary key (id)) engine=InnoDB;
create table cash_register_entries (id bigint not null auto_increment, amount decimal(38,2) not null, cash_register_id bigint not null, created_at datetime(6), created_by bigint, description varchar(255) not null, payment_method varchar(255), receipt_number varchar(255), `time` datetime(6), transaction_id bigint, type varchar(255) not null, primary key (id)) engine=InnoDB;
create table cash_registers (id bigint not null auto_increment, association_id bigint not null, closed_at datetime(6), closed_by bigint, closing_balance decimal(38,2), created_at datetime(6), `date` date not null, notes varchar(255), opened_at datetime(6), opened_by bigint not null, opening_balance decimal(38,2) not null, status varchar(255), total_expense decimal(38,2), total_income decimal(38,2), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table certificate_templates (id bigint not null auto_increment, is_active bit, association_id bigint not null, background_image_path varchar(255), body_html TEXT not null, created_at datetime(6), footer_image_path varchar(255), header_image_path varchar(255), merge_fields TEXT, name varchar(255) not null, orientation varchar(255), paper_size varchar(255), signatory_roles TEXT, type varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table communication_recipients (id bigint not null auto_increment, communication_id bigint not null, email varchar(255) not null, error_message varchar(255), name varchar(255), sent_at datetime(6), status varchar(255), user_id bigint, primary key (id)) engine=InnoDB;
create table communication_templates (id bigint not null auto_increment, is_active bit, association_id bigint not null, body_html TEXT not null, body_text TEXT, category varchar(255), created_at datetime(6), `language` varchar(255), merge_fields TEXT, name varchar(255) not null, subject varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table communications (id bigint not null auto_increment, association_id bigint not null, body_html TEXT not null, body_text TEXT, channel varchar(255), created_at datetime(6), delivered_count integer, failed_count integer, notes varchar(255), scheduled_at datetime(6), segment_filter TEXT, sender_email varchar(255), sender_name varchar(255), sent_at datetime(6), sent_by bigint, status varchar(255), subject varchar(255) not null, template_id bigint, total_recipients integer, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table coupon_activities (coupon_id bigint not null, activity_id bigint not null, primary key (coupon_id, activity_id)) engine=InnoDB;
create table coupon_events (coupon_id bigint not null, event_id bigint not null, primary key (coupon_id, event_id)) engine=InnoDB;
create table coupons (id bigint not null auto_increment, association_id bigint not null, code varchar(255) not null, created_at datetime(6), current_uses integer, description varchar(255), discount_type varchar(255) not null, discount_value decimal(38,2) not null, end_date date, is_active bit, max_uses integer, min_amount decimal(38,2), start_date date, primary key (id)) engine=InnoDB;
create table event_participants (id bigint not null auto_increment, amount_paid decimal(38,2), check_in_time datetime(6), guest_email varchar(255), guest_name varchar(255), invoice_id bigint, notes TEXT, payment_date date, payment_method varchar(255), payment_status varchar(255) not null, registration_date datetime(6), status varchar(255) not null, event_id bigint not null, user_id bigint, primary key (id)) engine=InnoDB;
create table events (id bigint not null auto_increment, address varchar(255), association_id bigint, cancellation_date datetime(6), cancellation_reason varchar(255), cost_member decimal(38,2), cost_non_member decimal(38,2), created_at datetime(6), description varchar(255), end_datetime datetime(6), generate_invoice bit, is_public bit, location varchar(255), max_participants integer, name varchar(255), require_registration bit, start_datetime datetime(6), status varchar(255), type varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table fiscal_comparisons (id bigint not null auto_increment, association_id bigint not null, base_year integer not null, checksum varchar(255), comparison_year integer not null, created_at datetime(6), csv_path varchar(255), data_snapshot TEXT, generated_at datetime(6), generated_by bigint, pdf_path varchar(255), primary key (id)) engine=InnoDB;
create table fiscal_year_closures (id bigint not null auto_increment, association_id bigint not null, closed_at datetime(6), closed_by bigint, created_at datetime(6), members_count integer, net_balance decimal(38,2), notes TEXT, status varchar(255) not null, total_expenses decimal(38,2), total_income decimal(38,2), updated_at datetime(6), `year` integer not null, primary key (id)) engine=InnoDB;
create table import_logs (id bigint not null auto_increment, association_id bigint not null, completed_at datetime(6), created_at datetime(6), entity_type varchar(255) not null, error_rows integer, errors_detail TEXT, file_checksum varchar(255), file_name varchar(255), imported_by bigint, imported_rows integer, skipped_rows integer, started_at datetime(6), status varchar(255), total_rows integer, primary key (id)) engine=InnoDB;
create table institutional_signatures (id bigint not null auto_increment, is_active bit, association_id bigint not null, created_at datetime(6), signature_image longblob, signature_mime_type varchar(255), signer_name varchar(255) not null, signer_role varchar(255) not null, signer_title varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table inventory_items (id bigint not null auto_increment, acquisition_method varchar(255), assigned_to bigint, association_id bigint not null, category varchar(255), condition_status varchar(255), created_at datetime(6), current_value decimal(38,2), depreciation_years integer, description varchar(255), inventory_code varchar(255), location varchar(255), name varchar(255), notes TEXT, photo_path varchar(255), purchase_date date, purchase_price decimal(38,2), quantity integer, status varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table inventory_loans (id bigint not null auto_increment, actual_return_date datetime(6), condition_on_loan varchar(255), condition_on_return varchar(255), created_at datetime(6), expected_return_date datetime(6), item_id bigint not null, loan_date datetime(6) not null, notes TEXT, status varchar(255) not null, updated_at datetime(6), user_association_id bigint not null, primary key (id)) engine=InnoDB;
create table invoice_checks (id bigint not null auto_increment, association_id bigint not null, check_date datetime(6), checked_by bigint, created_at datetime(6), numbering_issues TEXT, numbering_ok bit, overdue_amount decimal(38,2), overdue_count integer, payment_issues TEXT, payment_ok bit, pdf_path varchar(255), total_amount decimal(38,2), total_collected decimal(38,2), total_invoices integer, total_outstanding decimal(38,2), `year` integer not null, primary key (id)) engine=InnoDB;
create table invoices (id bigint not null auto_increment, activity_id bigint, amount decimal(38,2) not null, association_id bigint not null, cancellation_reason varchar(255), created_at datetime(6), description varchar(255), due_date date, event_id bigint, file_path varchar(255), is_cancelled bit, is_paid bit, issue_date date not null, notes TEXT, number varchar(255) not null, payment_date date, type varchar(255) not null, updated_at datetime(6), user_association_id bigint, primary key (id)) engine=InnoDB;
create table issued_certificates (id bigint not null auto_increment, activity_id bigint, association_id bigint not null, body_snapshot TEXT, certificate_number varchar(255) not null, checksum varchar(255), created_at datetime(6), event_id bigint, issue_date date not null, issued_by bigint, pdf_path varchar(255), qr_code_data varchar(255), revoked_at datetime(6), revoked_reason varchar(255), signatories TEXT, status varchar(255), template_id bigint not null, title varchar(255) not null, user_id bigint not null, primary key (id)) engine=InnoDB;
create table journal_entries (id bigint not null auto_increment, association_id bigint not null, created_at datetime(6), `date` date not null, description varchar(255) not null, reference_id varchar(255), transaction_id bigint, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table journal_entry_lines (id bigint not null auto_increment, credit decimal(38,2) not null, debit decimal(38,2) not null, description varchar(255), account_id bigint not null, journal_entry_id bigint not null, primary key (id)) engine=InnoDB;
create table medical_certificates (id bigint not null auto_increment, association_id bigint not null, certificate_type varchar(255) not null, created_at datetime(6), expiry_date date, file_path varchar(255), issue_date date, issued_by varchar(255), medical_facility varchar(255), member_id bigint not null, notes varchar(255), status varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table member_consents (id bigint not null auto_increment, association_id bigint not null, consent_type varchar(255) not null, created_at datetime(6), granted bit not null, granted_at datetime(6), lawful_basis varchar(255), member_id bigint not null, notes varchar(255), revoked_at datetime(6), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table members (id bigint not null auto_increment, address varchar(255), birth_date date, completeness_score integer, created_at datetime(6), email varchar(255), first_name varchar(255), fiscal_code varchar(255), last_name varchar(255), member_category varchar(255), member_type varchar(255), membership_status varchar(255), phone varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
create table notifications (id bigint not null auto_increment, created_at datetime(6), is_read bit, message varchar(255) not null, related_entity_id bigint, related_entity_type varchar(255), title varchar(255) not null, type varchar(255) not null, user_id bigint not null, primary key (id)) engine=InnoDB;
create table payment_methods (id bigint not null auto_increment, association_id bigint not null, configuration TEXT, created_at datetime(6), fixed_commission decimal(38,2), has_commission bit, is_active bit, name varchar(255) not null, percentage_commission decimal(38,2), type varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table resource_bookings (id bigint not null auto_increment, activity_id bigint, approved_at datetime(6), approved_by bigint, association_id bigint not null, booked_by bigint not null, created_at datetime(6), end_datetime datetime(6) not null, event_id bigint, notes varchar(255), recurrence_rule varchar(255), resource_id bigint not null, start_datetime datetime(6) not null, status varchar(255), title varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table resources (id bigint not null auto_increment, is_active bit, association_id bigint not null, capacity integer, cost_per_hour decimal(38,2), created_at datetime(6), description varchar(255), image_path varchar(255), location varchar(255), name varchar(255) not null, notes varchar(255), requires_approval bit, type varchar(255) not null, updated_at datetime(6), primary key (id)) engine=InnoDB;
create table sync_config (id bigint not null auto_increment, auto_sync_enabled bit, last_sync_time datetime(6), remote_db_name varchar(255), remote_host varchar(255), remote_password varchar(255), remote_port integer, remote_username varchar(255), primary key (id)) engine=InnoDB;
create table transactions (id bigint not null auto_increment, activity_id bigint, amount decimal(38,2) not null, association_id bigint not null, category varchar(255), category_id bigint, commission_amount decimal(38,2), cost_center varchar(255), created_at datetime(6), created_by bigint, `date` date not null, description varchar(255), event_id bigint, fund_id bigint, inventory_item_id bigint, is_renewal bit, is_verified bit, membership_id bigint, net_amount decimal(38,2), payment_method varchar(255), project_id bigint, quota_period varchar(255), receipt_path varchar(255), reference_id varchar(255), renewal_year integer, type enum ('EXPENSE','INCOME') not null, updated_at datetime(6), user_id bigint, verified_at datetime(6), verified_by bigint, primary key (id)) engine=InnoDB;
create table user_associations (id bigint not null auto_increment, created_at datetime(6), expiration_date date, is_board_member bit, join_date date, last_renewal_date date, membership_card_number varchar(255), notes TEXT, role varchar(255) not null, status varchar(255) not null, updated_at datetime(6), association_id bigint not null, user_id bigint not null, primary key (id)) engine=InnoDB;
create table users (id bigint not null auto_increment, address varchar(255), birth_date date, birth_place varchar(255), city varchar(255), created_at datetime(6), email varchar(255), first_name varchar(255) not null, gender varchar(255), last_name varchar(255) not null, phone varchar(255), tax_code varchar(255), updated_at datetime(6), zip_code varchar(255), primary key (id)) engine=InnoDB;
create table volunteer_expenses (id bigint not null auto_increment, amount decimal(38,2) not null, created_at datetime(6), description varchar(255) not null, expense_date date not null, receipt_path varchar(255), shift_id bigint, status varchar(255) not null, transaction_id bigint, updated_at datetime(6), volunteer_id bigint not null, primary key (id)) engine=InnoDB;
create table volunteer_shifts (id bigint not null auto_increment, activity_id bigint, description TEXT, end_time datetime(6), event_id bigint, hourly_value decimal(38,2), hours_worked decimal(38,2), role varchar(255), start_time datetime(6), status varchar(255), verified_at datetime(6), volunteer_id bigint, verified_by bigint, primary key (id)) engine=InnoDB;
create table volunteers (id bigint not null auto_increment, availability varchar(255), created_at datetime(6), member_id bigint, notes varchar(255), skills varchar(255), status varchar(255), updated_at datetime(6), primary key (id)) engine=InnoDB;
